+#include "jfr/jfrEvents.hpp"
+#include "jfr/periodic/sampling/jfrStackTraceRequest.hpp"
+#include "jfr/periodic/sampling/jfrStackWalker.hpp"
+#include "jfr/support/jfrThreadLocal.hpp"
